134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        normalizeOwnerFields(owner);
138	        // Enforce the pre-persistence policies that can reject the new owner outright.
139	        rejectDisallowedOwnerCreation(owner);
140	        // Identify any existing owners who share a household (same last name and address,
141	        // compared case-insensitively with collapsed whitespace) with the owner being created.
142	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
143	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
144	        // Reject creating an owner who shares a household with an existing owner, unless the
145	        // request explicitly opts in with 'sharesHousehold' true.
146	        if (!sharesHousehold && !householdMembers.isEmpty()) {
147	            throw new DuplicateHouseholdException(
148	                "An owner with the same last name and address already exists");
149	        }
150	        // When opting in and joining an existing household, assign the new owner and every
151	        // existing member the same stable household identifier derived from the last name and
152	        // address, so all owners of the household share one 'householdId'.
153	        if (sharesHousehold && !householdMembers.isEmpty()) {
